-            this.keySelector = keySelector;
-        }
+    record ToMapKeyValueSelector<K, V, T>(Function<? super T, ? extends V> valueSelector,
+            Function<? super T, ? extends K> keySelector) implements BiConsumer<Map<K, V>, T> {

         @Override
         public void accept(Map<K, V> m, T t) throws Throwable {
@@ -395,17 +383,10 @@ public final class Functions {
         return new ToMapKeyValueSelector<>(valueSelector, keySelector);
     }

