-            this.collectionFactory = collectionFactory;
-            this.valueSelector = valueSelector;
-            this.keySelector = keySelector;
-        }
+    record ToMultimapKeyValueSelector<K, V, T>(
+            Function<? super K, ? extends Collection<? super V>> collectionFactory,
+            Function<? super T, ? extends V> valueSelector,
+            Function<? super T, ? extends K> keySelector) implements BiConsumer<Map<K, Collection<V>>, T> {

         @SuppressWarnings("unchecked")
         @Override
@@ -496,22 +477,17 @@ public final class Functions {
             }
         }

-    static final class Array5Func<T1, T2, T3, T4, T5, R> implements Function<Object[], R> {
-        private final Function5<T1, T2, T3, T4, T5, R> f;
-
-        Array5Func(Function5<T1, T2, T3, T4, T5, R> f) {
-            this.f = f;
-        }
+    record Array5Func<T1, T2, T3, T4, T5, R>(Function5<T1, T2, T3, T4, T5, R> f) implements Function<Object[], R> {

